import fs from 'node:fs';
function edit(path, pairs) {
  let s = fs.readFileSync(path, 'utf8');
  for (const [a, b] of pairs) {
    if (!s.includes(a)) throw new Error(path + ': ' + a);
    s = s.split(a).join(b);
  }
  fs.writeFileSync(path, s);
}
fs.writeFileSync('src/carstatsof.ts', `// carstatsof.ts - the measured garage numbers of the roster in play: the real cars' table under
// ?realcars=1 (realcars.ts), else the roster's (both generated by tools/carstats.mjs).
import type { CarStat } from './ai/types.ts';
import { CAR_STATS } from './carstats.ts';
import { REAL_CAR_STATS } from './carstatsreal.ts';
import { FIX } from './core/fixes.ts';

export const STATS: Record<string, CarStat> = FIX.realCars ? REAL_CAR_STATS : CAR_STATS;
`);
edit('src/ai/line.ts', [['import { CAR_STATS } from "../carstats.ts";', 'import { STATS } from "../carstatsof.ts";'],
  ['stats: CarStat = CAR_STATS[carId] || {};', 'stats: CarStat = STATS[carId] || {};']]);
edit('src/menu/garage.ts', [["import { CAR_STATS } from '../carstats.ts';", "import { STATS } from '../carstatsof.ts';"],
  ['spec: Partial<CarStat> = CAR_STATS[car.id] || {};', 'spec: Partial<CarStat> = STATS[car.id] || {};'],
  ['spec: Partial<CarStat> = CAR_STATS[carId] || {};', 'spec: Partial<CarStat> = STATS[carId] || {};']]);
console.log('ok');
